curl --location 'https://maas-api.antdigital.com/v1/systemone' \
--header 'Content-Type: application/json' \
--header 'Authorization: Bearer $API_KEY' \
--data '{
  "model": "lingdt-decision-1.0",
  "state": {"situation": "同一笔订单被扣款两次,客服承诺 3 个工作日内退款,一周过去仍未到账。",
            "order": "SO-10086", "amount": "199元"},
  "questions": {
    "department": {"type": "choice", "instructions": "应该由哪个部门处理该工单?",
                   "criteria": {"billing": "账单、扣款、退款相关问题", "shipping": "物流与配送问题",
                                "account": "账号与登录问题", "other": "其他问题"}},
    "severity":   {"type": "score",  "instructions": "该客诉的严重程度是几级?",
                   "criteria": ["一般", "较严重", "严重", "非常严重"]},
    "urgent":     {"type": "noul",   "instructions": "综合 `department` 与 `severity`,对照规则判断:该工单是否需要在 24 小时内优先处理?",
                   "criteria": {"true": "资金被实际占用且已超出承诺时限,需 24 小时内人工介入",
                                "false": "仍在承诺处理时限内,按常规时限处理即可"}},
    "queue":      {"type": "choice", "instructions": "综合 `urgent` 与 `department`,该工单应进入哪条处理队列?",
                   "criteria": {"quick_refund": "快速退款通道:已确认的重复扣款且需优先处理",
                                "manual_review": "人工复核队列:判定存疑或需要补充证据",
                                "normal_track": "常规跟进:一般严重程度,按正常时限处理"}}
  },
  "options": {"dag": {"edges": {
    "urgent": {"depends": ["department", "severity"]},
    "queue":  {"depends": ["urgent", "department"]}
  }}}
}'
# edges 的 key 为下游问题 id,depends 为其依赖的上游问题 id 列表;未出现在 edges 中的问题视为无依赖;



